export const ControlledAddFilter: StoryObj = {
  render: ControlledAddFilterExample,
  parameters: { sourceCode: 'import AddFilter from \'@semcore/ui/add-filter\';\nimport { Box } from \'@semcore/ui/base-components\';\nimport { FilterTrigger } from \'@semcore/ui/base-trigger\';\nimport { Chart } from \'@semcore/ui/d3-chart\';\nimport type { SelectValue } from \'@semcore/ui/select\';\nimport Select from \'@semcore/ui/select\';\nimport React from \'react\';\n\nconst defaultFilterData = {\n  size: \'\',\n  Color: \'\',\n};\n\ntype FilterKeys = keyof typeof defaultFilterData;\ntype FilterData = Record<FilterKeys, string>;\n\nconst sizes = [\'Small\', \'Medium\', \'Large\'];\nconst colors = [\'Blue\', \'Green\', \'Yellow\'];\n\nconst filters: Array<{ name: FilterKeys; values: string[] }> = [\n  {\n    name: \'Color\',\n    values: colors,\n  },\n];\n\nconst Demo = () => {\n  const [filterData, setFilterData] =\n          React.useState<FilterData>(defaultFilterData);\n  const [visibleFilters, setVisibleFilters] = React.useState<string[]>([]);\n  const [visible, setVisible] = React.useState<Record<FilterKeys, boolean>>({\n    size: false,\n    Color: false,\n  });\n\n  const updateFilterData = (value: string, name: string) => {\n    if (name === \'Color\') {\n      const newVisibleFilters = new Set(visibleFilters);\n      newVisibleFilters.add(\'Color\');\n      setVisibleFilters(Array.from(newVisibleFilters));\n      setVisible({\n        size: false,\n        Color: false,\n      });\n    }\n\n    setFilterData((prevData) => {\n      return { ...prevData, ...{ [name]: value } };\n    });\n  };\n\n  const clearField = React.useCallback(\n    (name: keyof FilterData) => {\n      const tempData = { ...filterData, [name]: \'\' };\n      setFilterData(tempData);\n    },\n    [filterData],\n  );\n\n  const handleVisible = React.useCallback((key: FilterKeys) => (visible: boolean) => {\n    setVisible((prevVisible) => {\n      return {\n        ...prevVisible,\n        [key]: visible,\n      };\n    });\n  }, [visible, setVisible]);\n\n  const handleVisibleFiltersChange = React.useCallback((newVisibleFilters: string[]) => {\n    const visibleFiltersSet = new Set(visibleFilters);\n    if (newVisibleFilters.length > visibleFiltersSet.size) {\n      const newVisibleFilter = newVisibleFilters.find((key) => !visibleFiltersSet.has(key));\n\n      if (newVisibleFilter) {\n        setVisible((prevState) => {\n          return {\n            ...prevState,\n            [newVisibleFilter]: true,\n          };\n        });\n      }\n    }\n\n    setVisibleFilters(newVisibleFilters);\n  }, [visibleFilters]);\n\n  return (\n    <Box>\n      <AddFilter\n        filterData={filterData}\n        onClearAll={() => {\n          setFilterData(defaultFilterData);\n        }}\n        gap={2}\n        flexWrap\n        visibleFilters={visibleFilters}\n        onVisibleFiltersChange={handleVisibleFiltersChange}\n      >\n        <Select\n          value={filterData.size}\n          onChange={(v: string) => updateFilterData(v, \'size\')}\n        >\n          <Select.Trigger\n            empty={!filterData.size}\n            placeholder=\'Size\'\n            tag={FilterTrigger}\n            onClear={() => clearField(\'size\')}\n            aria-label=\'Size\'\n          >\n            <span aria-hidden>Size:</span> {filterData.size}\n          </Select.Trigger>\n          <Select.Menu aria-label=\'Size\'>\n            {sizes.map((item, idx) => (\n              <Select.Option key={idx} value={item}>\n                {item}\n              </Select.Option>\n            ))}\n          </Select.Menu>\n        </Select>\n\n        {filters.map(({ name, values }) => {\n          return (\n            <AddFilter.Select\n              key={name}\n              name={name}\n              displayName={name}\n              onChange={(v: SelectValue) => {\n                if (typeof v === \'string\') {\n                  updateFilterData(v, name);\n                }\n              }}\n              visible={visible[name]}\n              onVisibleChange={handleVisible(name)}\n            >\n              <AddFilter.Select.Trigger\n                placeholder={name}\n                aria-label={name}\n                onClear={() => {\n                  clearField(name);\n                }}\n              >\n                <span aria-hidden>{name}:</span> {filterData[name]}\n              </AddFilter.Select.Trigger>\n              <AddFilter.Select.Menu aria-label={name}>\n                {values.map((item, idx) => (\n                  <AddFilter.Select.Option key={idx} value={item}>\n                    {item}\n                  </AddFilter.Select.Option>\n                ))}\n              </AddFilter.Select.Menu>\n            </AddFilter.Select>\n          );\n        })}\n      </AddFilter>\n\n      <Box>\n        Sizes:\n        <Chart.Cigarette\n          data={{\n            [sizes[0]]: 1,\n            [sizes[1]]: 2,\n            [sizes[2]]: 3,\n          }}\n          plotWidth={400}\n          plotHeight={28}\n          aria-label=\'Sizes\'\n          onClick={(key: string) => {\n            updateFilterData(key, \'size\');\n          }}\n        />\n      </Box>\n\n      <Box>\n        Colors:\n        <Chart.Cigarette\n          data={{\n            [colors[0]]: 1,\n            [colors[1]]: 2,\n            [colors[2]]: 3,\n          }}\n          plotWidth={400}\n          plotHeight={28}\n          aria-label=\'Colors\'\n          onClick={(key: string) => {\n            updateFilterData(key, \'Color\');\n          }}\n        />\n      </Box>\n    </Box>\n  );\n};\n\nexport default Demo;\n' },
  parameters: { sourceCode: 'import AddFilter from \'@semcore/ui/add-filter\';\nimport { Box } from \'@semcore/ui/base-components\';\nimport { FilterTrigger } from \'@semcore/ui/base-trigger\';\nimport { Chart } from \'@semcore/ui/d3-chart\';\nimport type { SelectValue } from \'@semcore/ui/select\';\nimport Select from \'@semcore/ui/select\';\nimport React from \'react\';\n\nconst defaultFilterData = {\n  size: \'\',\n  Color: \'\',\n};\n\ntype FilterKeys = keyof typeof defaultFilterData;\ntype FilterData = Record<FilterKeys, string>;\n\nconst sizes = [\'Small\', \'Medium\', \'Large\'];\nconst colors = [\'Blue\', \'Green\', \'Yellow\'];\n\nconst filters: Array<{ name: FilterKeys; values: string[] }> = [\n  {\n    name: \'Color\',\n    values: colors,\n  },\n];\n\nconst Demo = () => {\n  const [filterData, setFilterData] =\n          React.useState<FilterData>(defaultFilterData);\n  const [visibleFilters, setVisibleFilters] = React.useState<string[]>([]);\n  const [visible, setVisible] = React.useState<Record<FilterKeys, boolean>>({\n    size: false,\n    Color: false,\n  });\n\n  const updateFilterData = (value: string, name: string) => {\n    if (name === \'Color\') {\n      const newVisibleFilters = new Set(visibleFilters);\n      newVisibleFilters.add(\'Color\');\n      setVisibleFilters(Array.from(newVisibleFilters));\n      setVisible({\n        size: false,\n        Color: false,\n      });\n    }\n\n    setFilterData((prevData) => {\n      return { ...prevData, ...{ [name]: value } };\n    });\n  };\n\n  const clearField = React.useCallback(\n    (name: keyof FilterData) => {\n      const tempData = { ...filterData, [name]: \'\' };\n      setFilterData(tempData);\n    },\n    [filterData],\n  );\n\n  const handleVisible = React.useCallback((key: FilterKeys) => (visible: boolean) => {\n    setVisible((prevVisible) => {\n      return {\n        ...prevVisible,\n        [key]: visible,\n      };\n    });\n  }, [visible, setVisible]);\n\n  const handleVisibleFiltersChange = React.useCallback((newVisibleFilters: string[]) => {\n    const visibleFiltersSet = new Set(visibleFilters);\n    if (newVisibleFilters.length > visibleFiltersSet.size) {\n      const newVisibleFilter = newVisibleFilters.find((key) => !visibleFiltersSet.has(key));\n\n      if (newVisibleFilter) {\n        setVisible((prevState) => {\n          return {\n            ...prevState,\n            [newVisibleFilter]: true,\n          };\n        });\n      }\n    }\n\n    setVisibleFilters(newVisibleFilters);\n  }, [visibleFilters]);\n\n  return (\n    <Box>\n      <AddFilter\n        filterData={filterData}\n        onClearAll={() => {\n          setFilterData(defaultFilterData);\n        }}\n        gap={2}\n        flexWrap\n        visibleFilters={visibleFilters}\n        onVisibleFiltersChange={handleVisibleFiltersChange}\n      >\n        <Select\n          value={filterData.size}\n          onChange={(v: string) => updateFilterData(v, \'size\')}\n        >\n          <Select.Trigger\n            empty={!filterData.size}\n            placeholder=\'Size\'\n            tag={FilterTrigger}\n            onClear={() => clearField(\'size\')}\n            aria-label=\'Size\'\n          >\n            <span aria-hidden>Size:</span> {filterData.size}\n          </Select.Trigger>\n          <Select.Menu aria-label=\'Size\'>\n            {sizes.map((item, idx) => (\n              <Select.Option key={idx} value={item}>\n                {item}\n              </Select.Option>\n            ))}\n          </Select.Menu>\n        </Select>\n\n        {filters.map(({ name, values }) => {\n          return (\n            <AddFilter.Select\n              key={name}\n              name={name}\n              displayName={name}\n              onChange={(v: SelectValue) => {\n                if (typeof v === \'string\') {\n                  updateFilterData(v, name);\n                }\n              }}\n              visible={visible[name]}\n              onVisibleChange={handleVisible(name)}\n            >\n              <AddFilter.Select.Trigger\n                placeholder={name}\n                aria-label={name}\n                onClear={() => {\n                  clearField(name);\n                }}\n              >\n                <span aria-hidden>{name}:</span> {filterData[name]}\n              </AddFilter.Select.Trigger>\n              <AddFilter.Select.Menu aria-label={name}>\n                {values.map((item, idx) => (\n                  <AddFilter.Select.Option key={idx} value={item}>\n                    {item}\n                  </AddFilter.Select.Option>\n                ))}\n              </AddFilter.Select.Menu>\n            </AddFilter.Select>\n          );\n        })}\n      </AddFilter>\n\n      <Box>\n        Sizes:\n        <Chart.Cigarette\n          data={{\n            [sizes[0]]: 1,\n            [sizes[1]]: 2,\n            [sizes[2]]: 3,\n          }}\n          plotWidth={400}\n          plotHeight={28}\n          aria-label=\'Sizes\'\n          onClick={(key: string) => {\n            updateFilterData(key, \'size\');\n          }}\n        />\n      </Box>\n\n      <Box>\n        Colors:\n        <Chart.Cigarette\n          data={{\n            [colors[0]]: 1,\n            [colors[1]]: 2,\n            [colors[2]]: 3,\n          }}\n          plotWidth={400}\n          plotHeight={28}\n          aria-label=\'Colors\'\n          onClick={(key: string) => {\n            updateFilterData(key, \'Color\');\n          }}\n        />\n      </Box>\n    </Box>\n  );\n};\n\nexport default Demo;\n' },
};
